// Ordinal model of momentary mood (1 Sad, 2 Meh, 3 Happy).
//
//   P(y_i <= k) = logistic(c_k - eta_i),  k = 1, 2
//   eta_i = time_of_day[s] + weekday[w] + x_d' beta + u_d
//   u_d = phi * u_(d-1) + sigma * e_d          latent daily mood, stationary AR(1)
//
// phi lies in (-1, 1) with (phi + 1) / 2 ~ Beta(2, 2), a prior symmetric around
// zero, so the direction of day-to-day carry-over is estimated, not assumed.
//
// Predictors are standardized; missing cells are imputed as N(0, 1) parameters
// (missing at random). Confirmatory factors have normal(0, 0.5) priors, the scale
// passed as data so that sensitivity analyses can vary it; the others share a
// hierarchical shrinkage prior, beta = tau * beta_z.
data {
  int<lower=1> N;                                 // reports
  int<lower=1> D;                                 // calendar days from first to last report
  int<lower=1> R;                                 // days with reports (rows of X)
  int<lower=0> P;                                 // predictors
  array[N] int<lower=1, upper=3> y;
  array[N] int<lower=1, upper=3> slot;            // morning, afternoon, evening
  array[N] int<lower=1, upper=7> weekday;         // 1 = Monday
  array[N] int<lower=1, upper=D> day;
  array[N] int<lower=1, upper=R> rated_day;       // row of X for each report
  matrix[R, P] X;                                 // missing cells hold 0
  int<lower=0> M;
  array[M] int<lower=1, upper=R> miss_row;
  array[M] int<lower=1, upper=P> miss_col;
  real<lower=0> prior_scale;                      // scale of the half-normal prior on tau
  real<lower=0> confirmatory_scale;               // prior SD of the confirmatory factors (0.5)
  array[P] int<lower=0, upper=1> pooled;          // 0: confirmatory factor, 1: shares tau
}
parameters {
  ordered[2] cutpoints;
  sum_to_zero_vector[3] time_of_day;
  sum_to_zero_vector[7] weekday_effect;
  real<lower=-1, upper=1> phi;
  real<lower=0> sigma_day;
  vector[D] z_day;
  real<lower=0> tau;
  vector[P] beta_z;
  vector[M] x_missing;
}
transformed parameters {
  // Factors of the confirmatory hypotheses have their own normal(0, confirmatory_scale) prior;
  // the others share the scale tau, a hierarchical shrinkage prior. Pooling the
  // confirmatory factors with many null ones would shrink them by about half.
  vector[P] beta;
  for (j in 1:P) {
    beta[j] = (pooled[j] ? tau : confirmatory_scale) * beta_z[j];
  }
  // Non-centered AR(1), started from its stationary distribution.
  vector[D] mood_day;
  mood_day[1] = sigma_day * z_day[1] / sqrt(1 - square(phi));
  for (d in 2:D) {
    mood_day[d] = phi * mood_day[d - 1] + sigma_day * z_day[d];
  }
}
model {
  vector[N] eta = time_of_day[slot] + weekday_effect[weekday] + mood_day[day];
  if (P > 0) {
    matrix[R, P] X_full = X;
    for (m in 1:M) {
      X_full[miss_row[m], miss_col[m]] = x_missing[m];
    }
    eta += (X_full * beta)[rated_day];
  }
  cutpoints ~ normal([-1, 1]', 1.5);
  // On a sum-to-zero vector this matches PyMC's ZeroSumNormal(0.5).
  time_of_day ~ normal(0, 0.5);
  weekday_effect ~ normal(0, 0.5);
  target += beta_lpdf((phi + 1) / 2 | 2, 2);
  sigma_day ~ normal(0, 1);
  z_day ~ std_normal();
  tau ~ normal(0, prior_scale);
  beta_z ~ std_normal();
  x_missing ~ std_normal();
  y ~ ordered_logistic(eta, cutpoints);
}
// Secondary outcome: the evening rating of the day, 0 to 10 (coded 1 to 11).
//
//   P(y_d <= k) = logistic(c_k - eta_d),  k = 1, ..., 10
//   eta_d = weekday[w] + x_d' beta + u_d
//   u_d = phi * u_(d-1) + sigma * e_d          latent day effect, stationary AR(1)
//
// The same factors, timing rules, weekday effects and priors as mood.stan
// (confirmatory factors unpooled, the others under shared shrinkage), with ten
// ordered cutpoints. With one rating per day, the day effect is identified
// only through its autocorrelation.
data {
  int<lower=1> N;                                 // days with a rating
  int<lower=1> D;                                 // calendar days from first to last rating
  int<lower=0> P;                                 // factors
  array[N] int<lower=1, upper=11> y;
  array[N] int<lower=1, upper=7> weekday;         // 1 = Monday
  array[N] int<lower=1, upper=D> day;
  matrix[N, P] X;                                 // missing cells hold 0
  int<lower=0> M;
  array[M] int<lower=1, upper=N> miss_row;
  array[M] int<lower=1, upper=P> miss_col;
  real<lower=0> prior_scale;                      // scale of the half-normal prior on tau
  real<lower=0> confirmatory_scale;               // prior SD of the confirmatory factors (0.5)
  array[P] int<lower=0, upper=1> pooled;          // 0: confirmatory factor, 1: shares tau
}
parameters {
  ordered[10] cutpoints;
  sum_to_zero_vector[7] weekday_effect;
  real<lower=-1, upper=1> phi;
  real<lower=0> sigma_day;
  vector[D] z_day;
  real<lower=0> tau;
  vector[P] beta_z;
  vector[M] x_missing;
}
transformed parameters {
  // Factors of the confirmatory hypotheses have their own normal(0, confirmatory_scale) prior;
  // the others share the scale tau, a hierarchical shrinkage prior. Pooling the
  // confirmatory factors with many null ones would shrink them by about half.
  vector[P] beta;
  for (j in 1:P) {
    beta[j] = (pooled[j] ? tau : confirmatory_scale) * beta_z[j];
  }
  vector[D] mood_day;
  mood_day[1] = sigma_day * z_day[1] / sqrt(1 - square(phi));
  for (d in 2:D) {
    mood_day[d] = phi * mood_day[d - 1] + sigma_day * z_day[d];
  }
}
model {
  vector[N] eta = weekday_effect[weekday] + mood_day[day];
  if (P > 0) {
    matrix[N, P] X_full = X;
    for (m in 1:M) {
      X_full[miss_row[m], miss_col[m]] = x_missing[m];
    }
    eta += X_full * beta;
  }
  cutpoints ~ normal(0, 3);
  weekday_effect ~ normal(0, 0.5);
  target += beta_lpdf((phi + 1) / 2 | 2, 2);
  sigma_day ~ normal(0, 1);
  z_day ~ std_normal();
  tau ~ normal(0, prior_scale);
  beta_z ~ std_normal();
  x_missing ~ std_normal();
  y ~ ordered_logistic(eta, cutpoints);
}
test_that("the model recovers a sleep effect from simulated data", {
  skip_if(Sys.getenv("ASOM_SLOW_TESTS") == "", "set ASOM_SLOW_TESTS=1 to fit the model")
  con <- new_study_db(SCHEMA)
  on.exit(DBI::dbDisconnect(con))
  beta <- replace(TRUE_BETA, "sleep_hours", 1) # a clear effect: 1 SD on the log-odds scale
  simulate_study(con, days = 60, seed = 11, beta = beta)
  ds <- load_dataset(con, 1L)
  fit <- fit_model(ds, STAN, file.path(tempdir(), "stan"), seed = 1, iter = 500)
  res <- summarize_fit(ds, fit)
  sleep <- Filter(function(p) p$field == "sleep_hours", res$predictors)[[1]]
  expect_gt(sleep$p_positive, 0.99)
  expect_equal(res$diagnostics$divergences, 0)
  expect_equal(sum(res$forecast$slots$morning), 1, tolerance = 0.01)
})

test_that("the day satisfaction model recovers a sleep effect", {
  skip_if(Sys.getenv("ASOM_SLOW_TESTS") == "", "set ASOM_SLOW_TESTS=1 to fit the model")
  con <- new_study_db(SCHEMA)
  on.exit(DBI::dbDisconnect(con))
  simulate_study(con, days = 120, seed = 12, beta = replace(TRUE_BETA, "sleep_hours", 1))
  ds <- load_day_dataset(con, 1L)
  res <- summarize_day_fit(ds, fit_day_model(ds, DAY_STAN, file.path(tempdir(), "stan"), seed = 1, iter = 500))
  sleep <- Filter(function(p) p$field == "sleep_hours", res$factors)[[1]]
  expect_gt(sleep$p_positive, 0.99)
  expect_equal(res$diagnostics$divergences, 0)
})

test_that("yes/no factors compare yes with no", {
  skip_if(Sys.getenv("ASOM_SLOW_TESTS") == "", "set ASOM_SLOW_TESTS=1 to fit the model")
  con <- new_study_db(SCHEMA)
  on.exit(DBI::dbDisconnect(con))
  simulate_study(con, days = 60, seed = 13)
  ds <- load_dataset(con, 1L)
  res <- summarize_fit(ds, fit_model(ds, STAN, file.path(tempdir(), "stan"), seed = 1, iter = 500))
  work <- Filter(function(p) p$field == "work_day", res$predictors)[[1]]
  # The probability change and the odds ratio agree in direction, and the evidence
  # label follows the unrounded probability.
  expect_equal(sign(work$d_happy_pp$est), sign(log(work$odds_ratio$est)))
  expect_equal(work$evidence, evidence(work$p_positive))
})

// Runs the R analysis and stores what it returns. R reads the database and
// writes JSON; this module is the only one that records runs.
import { execFile } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, rmSync } from "node:fs";
import path from "node:path";
import { promisify } from "node:util";
import { sha256 } from "./auth.ts";
import { DATA_DIR, DB_PATH, ROOT, RSCRIPT } from "./config.ts";
import { all, get, nowIso, run, transaction } from "./db.ts";
import { SLOTS, type Slot } from "./study.ts";

const execFileAsync = promisify(execFile);
const ANALYSIS_DIR = path.join(ROOT, "analysis");
const KEEP_FULL_RUNS = 10; // older runs keep only their effect estimates
const RUN_TIMEOUT_MS = 30 * 60 * 1000;
const STALE_MS = 2 * 3600 * 1000;

export type Status = "running" | "done" | "waiting" | "failed";

interface RunRow {
  id: number;
  user_id: number;
  status: Status;
  started_at: string;
  finished_at: string | null;
  n_ratings: number;
  n_days: number;
  data_fingerprint: string;
  results: string;
  message: string;
}

// The results JSON written by analysis/mood.R; see summarize_fit() there for its shape.
export type Results = Record<string, any>;
export type Run = Omit<RunRow, "results"> & { results: Results };

const parse = (row: RunRow | undefined): Run | null => (row ? { ...row, results: JSON.parse(row.results) as Results } : null);

export const getRun = (id: number): Run | null => parse(get<RunRow>("SELECT * FROM analysis_runs WHERE id = ?", id));
export const latestRun = (userId: number): Run | null =>
  parse(get<RunRow>("SELECT * FROM analysis_runs WHERE user_id = ? ORDER BY id DESC LIMIT 1", userId));
export const latestDone = (userId: number): Run | null =>
  parse(get<RunRow>("SELECT * FROM analysis_runs WHERE user_id = ? AND status = 'done' ORDER BY id DESC LIMIT 1", userId));
/** The newest finished run of any kind: tag comparisons exist even before the model can run. */
export const latestFinished = (userId: number): Run | null =>
  parse(get<RunRow>("SELECT * FROM analysis_runs WHERE user_id = ? AND status IN ('done', 'waiting') ORDER BY id DESC LIMIT 1", userId));
export const recentRuns = (userId: number, limit = 10) =>
  all<Omit<RunRow, "results">>(
    "SELECT id, user_id, status, started_at, finished_at, n_ratings, n_days, data_fingerprint, message FROM analysis_runs WHERE user_id = ? ORDER BY id DESC LIMIT ?",
    userId, limit,
  );

export const drawsPath = (runId: number): string => path.join(DATA_DIR, "posteriors", `run_${runId}.json`);

/** Changes whenever the data, the study start or the analysis code change, so hourly runs can skip. */
export function fingerprint(userId: number): string {
  const ratings = get("SELECT count(*) AS n, max(created_at) AS t FROM ratings WHERE user_id = ?", userId);
  const logs = get("SELECT count(*) AS n, max(updated_at) AS t FROM daily_logs WHERE user_id = ?", userId);
  const start = get("SELECT study_start FROM users WHERE id = ?", userId);
  const code = ["mood.R", "mood.stan", "refit.R"].map((f) => readFileSync(path.join(ANALYSIS_DIR, f), "utf8"));
  return sha256(JSON.stringify([ratings, logs, start, code]));
}

/** A fit is published only if it passed the convergence checks and used the study start now set. */
export const publishable = (run: Run | null, studyStart: string | null): run is Run =>
  Boolean(run?.results.diagnostics?.converged && studyStart && run.results.data?.study_start === studyStart);

/** A run still marked running after two hours was killed midway. */
export function markInterrupted(): void {
  run(
    "UPDATE analysis_runs SET status = 'failed', message = 'Interrupted before it finished.', finished_at = ? WHERE status = 'running' AND started_at < ?",
    nowIso(), new Date(Date.now() - STALE_MS).toISOString(),
  );
}

/** Fit the model for one user. Returns the run, or null when skipped. */
export async function refitUser(userId: number, options: { ifNewData?: boolean } = {}): Promise<Run | null> {
  const dataFingerprint = fingerprint(userId);
  const runId = transaction(() => {
    if (get("SELECT 1 FROM analysis_runs WHERE user_id = ? AND status = 'running'", userId)) return null;
    const last = get<{ data_fingerprint: string }>(
      "SELECT data_fingerprint FROM analysis_runs WHERE user_id = ? AND status != 'running' ORDER BY id DESC LIMIT 1", userId,
    );
    if (options.ifNewData && last?.data_fingerprint === dataFingerprint) return null;
    return Number(run("INSERT INTO analysis_runs (user_id, status, data_fingerprint) VALUES (?, 'running', ?)", userId, dataFingerprint).lastInsertRowid);
  });
  if (runId === null) return null;

  const out = path.join(DATA_DIR, "tmp", `run_${runId}.json`);
  mkdirSync(path.dirname(out), { recursive: true });
  mkdirSync(path.dirname(drawsPath(runId)), { recursive: true });
  try {
    await execFileAsync(
      RSCRIPT,
      [
        path.join(ANALYSIS_DIR, "refit.R"), "--db", DB_PATH, "--user", String(userId), "--out", out,
        "--draws", drawsPath(runId), "--stan-dir", path.join(DATA_DIR, "stan"), "--seed", String(runId),
      ],
      { timeout: RUN_TIMEOUT_MS, maxBuffer: 16 * 1024 * 1024 },
    );
    const output = JSON.parse(readFileSync(out, "utf8")) as { status: Status; message?: string; results?: Results };
    const results = output.results ?? {};
    run(
      "UPDATE analysis_runs SET status = ?, message = ?, results = ?, n_ratings = ?, n_days = ?, finished_at = ? WHERE id = ?",
      output.status, output.message ?? "", JSON.stringify(results), results.data?.n_ratings ?? 0, results.data?.n_rated_days ?? 0, nowIso(), runId,
    );
  } catch (error) {
    const stderr = String((error as { stderr?: unknown }).stderr ?? "");
    const lines = stderr.split("\n").filter((l) => l.trim() && !l.includes("built under R version"));
    const message = (lines.slice(-3).join(" ") || String(error)).slice(0, 500);
    run("UPDATE analysis_runs SET status = 'failed', message = ?, finished_at = ? WHERE id = ?", message, nowIso(), runId);
  } finally {
    rmSync(out, { force: true });
  }
  prune(userId);
  return getRun(runId);
}

/** Drop bulky series and posterior draws from older runs. */
function prune(userId: number): void {
  const old = all<{ id: number; results: string }>(
    "SELECT id, results FROM analysis_runs WHERE user_id = ? AND status = 'done' ORDER BY id DESC LIMIT -1 OFFSET ?",
    userId, KEEP_FULL_RUNS,
  );
  for (const row of old) {
    rmSync(drawsPath(row.id), { force: true });
    const results = JSON.parse(row.results) as Results;
    if ("daily_mood" in results) {
      for (const key of ["daily_mood", "ppc", "forecast"]) delete results[key];
      run("UPDATE analysis_runs SET results = ? WHERE id = ?", JSON.stringify(results), row.id);
    }
  }
}

interface Draws {
  cutpoints: number[][];
  time_of_day: number[][];
  weekday_effect: number[][];
  beta: number[][];
  phi: number[];
  sigma_day: number[];
  fields: string[];
  means: number[];
  sds: number[];
}

/** Deterministic standard normals (mulberry32 plus Box-Muller), so answers do not jitter. */
function normals(seed: number): () => number {
  let a = seed >>> 0;
  const uniform = () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  return () => Math.sqrt(-2 * Math.log(1 - uniform())) * Math.cos(2 * Math.PI * uniform());
}

const logistic = (x: number): number => 1 / (1 + Math.exp(-x));

/**
 * P(Sad, Meh, Happy) per slot on a typical day with the given predictor values
 * (blank means your average). The latent daily mood is averaged over its
 * long-run distribution, so this describes a typical day, not tomorrow.
 */
export function whatIf(runId: number, values: Record<string, string>, weekday: number): Record<Slot, number[]> {
  const file = drawsPath(runId);
  if (!existsSync(file)) throw new Error("The saved posterior for this run is gone; refit first.");
  const d = JSON.parse(readFileSync(file, "utf8")) as Draws;
  const x = d.fields.map((field, j) => {
    const raw = values[field]?.trim();
    if (!raw) return 0;
    const n = Number(raw);
    if (!Number.isFinite(n)) throw new RangeError("Please enter numbers only.");
    return (n - d.means[j]) / d.sds[j];
  });
  const z = normals(1);
  const totals = SLOTS.map(() => [0, 0, 0]);
  for (let s = 0; s < d.phi.length; s++) {
    const stationarySd = d.sigma_day[s] / Math.sqrt(1 - d.phi[s] ** 2);
    const base = x.reduce((sum, xj, j) => sum + d.beta[s][j] * xj, 0) + d.weekday_effect[s][weekday] + stationarySd * z();
    SLOTS.forEach((_, k) => {
      const eta = base + d.time_of_day[s][k];
      const belowMeh = logistic(d.cutpoints[s][0] - eta);
      const belowHappy = logistic(d.cutpoints[s][1] - eta);
      totals[k][0] += belowMeh;
      totals[k][1] += belowHappy - belowMeh;
      totals[k][2] += 1 - belowHappy;
    });
  }
  const round = (v: number) => Math.round((v / d.phi.length) * 1000) / 1000;
  return Object.fromEntries(SLOTS.map((slot, k) => [slot, totals[k].map(round)])) as Record<Slot, number[]>;
}
(function () {
  "use strict";
  const pp = (v) => (v > 0 ? "+" : "") + v.toFixed(1) + " pp";
  const pct = (v) => Math.round(v) + "%";
  const data = JSON.parse(document.getElementById("chart-data").textContent);

  if (data) {
    const mount = (id, fn) => { const el = document.getElementById(id); if (el) fn(el); };
    mount("effects-chart", (el) => Charts.forest(el, data.effects, {
      format: pp, axisLabel: "Change in chance of a Happy report (percentage points)",
    }));
    const levels = (rows) => rows.reduce((s, r) => s + r.est, 0) / rows.length;
    mount("tod-chart", (el) => Charts.forest(el, data.time_of_day, {
      format: pct, axisLabel: "Chance of a Happy report", zero: levels(data.time_of_day),
    }));
    mount("weekday-chart", (el) => Charts.forest(el, data.weekday, {
      format: pct, axisLabel: "Chance of a Happy report", zero: levels(data.weekday),
    }));
    if (data.daily) {
      mount("daily-chart", (el) => Charts.lines(el, {
        x: data.daily.dates,
        series: [{ name: "Chance of Happy", tone: "pos", values: data.daily.mean, lo: data.daily.lo, hi: data.daily.hi }],
      }, { yMin: 0, yMax: 1, format: (v) => Math.round(v * 100) + "%" }));
    }
  }

  // While a refit runs, poll until a newer run has finished, then reload.
  const status = document.getElementById("run-status");
  const startId = Number(status.dataset.runId);
  if (status.dataset.runStatus === "running" || "waiting" in status.dataset) {
    const started = Date.now();
    const timer = setInterval(async () => {
      if (Date.now() - started > 15 * 60 * 1000) return clearInterval(timer);
      const r = await fetch(status.dataset.url || "/analysis/status/", { credentials: "same-origin" }).catch(() => null);
      if (!r || !r.ok) return;
      const run = await r.json();
      const finished = run.status && run.status !== "running";
      if (finished && (run.id > startId || status.dataset.runStatus === "running")) {
        clearInterval(timer);
        location.replace(location.pathname);
      }
    }, 4000);
  }
})();

// Plain counts and shares for the dashboard. All inference happens in R.
import type { User } from "./auth.ts";
import { all, get } from "./db.ts";
import { addDays, SLOTS, studyDayAndSlot, weekdayIndex, WEEKDAYS } from "./study.ts";

export const currentStudyDay = (user: User) => studyDayAndSlot(new Date(), user.time_zone, user.day_start_hour);

/** The first study day: the configured study start, else the day of the first report. */
export function studyStart(user: User): string | null {
  return user.study_start || (get<{ d: string | null }>("SELECT min(study_date) AS d FROM ratings WHERE user_id = ?", user.id)?.d ?? null);
}

const answeredSlots = (user: User, from: string, to: string): number =>
  get<{ n: number }>(
    "SELECT count(*) AS n FROM (SELECT DISTINCT study_date, slot FROM ratings WHERE user_id = ? AND study_date BETWEEN ? AND ?)",
    user.id, from, to,
  )?.n ?? 0;

const daysBetween = (from: string, to: string) => Math.round((Date.parse(to) - Date.parse(from)) / 86_400_000) + 1;

/** Slots from `from` to `to` (today at the latest) that had begun by now: today counts only up to the current slot. */
function begunSlots(user: User, from: string, to: string): number {
  const { studyDate, slot } = currentStudyDay(user);
  return to < studyDate ? 3 * daysBetween(from, to) : 3 * (daysBetween(from, to) - 1) + SLOTS.indexOf(slot) + 1;
}

/**
 * Share of morning, afternoon and evening slots answered over the last `days`
 * study days, counting only slots since the study start that have begun.
 */
export function completion(user: User, days = 14): number {
  const today = currentStudyDay(user).studyDate;
  const start = studyStart(user);
  if (!start || start > today) return 0;
  const from = [addDays(today, -(days - 1)), start].sort().at(-1)!;
  return answeredSlots(user, from, today) / begunSlots(user, from, today);
}

/**
 * Adherence per week (Monday to Sunday) since the study start: slots answered out
 * of the slots that had begun by then. The protocol reviews the reminders when two
 * consecutive completed weeks fall below 50%.
 */
export function weeklyAdherence(user: User): { week: string; answered: number; eligible: number; share: number }[] {
  const today = currentStudyDay(user).studyDate;
  const start = studyStart(user);
  if (!start || start > today) return [];
  const rows = [];
  for (let week = addDays(start, -weekdayIndex(start)); week <= today; week = addDays(week, 7)) {
    const from = [week, start].sort().at(-1)!;
    const to = [addDays(week, 6), today].sort()[0];
    const eligible = begunSlots(user, from, to);
    const answered = answeredSlots(user, from, to);
    rows.push({ week, answered, eligible, share: answered / eligible });
  }
  return rows;
}

export interface Shares {
  n: number;
  sad: number | null;
  meh: number | null;
  happy: number | null;
}

function shares(ratings: number[]): Shares {
  const n = ratings.length;
  const share = (k: number) => (n ? ratings.filter((r) => r === k).length / n : null);
  return { n, sad: share(1), meh: share(2), happy: share(3) };
}

/** Share of Happy and Sad reports per week (Monday start); weeks with few reports stay blank. */
export function weeklyShares(user: User, weeks = 26) {
  const today = currentStudyDay(user).studyDate;
  const start = addDays(today, -(weekdayIndex(today) + 7 * (weeks - 1)));
  const rows = all<{ study_date: string; rating: number }>(
    "SELECT study_date, rating FROM ratings WHERE user_id = ? AND study_date >= ?", user.id, start,
  );
  const byWeek = new Map<string, number[]>();
  for (const r of rows) {
    const week = addDays(r.study_date, -weekdayIndex(r.study_date));
    byWeek.set(week, [...(byWeek.get(week) ?? []), r.rating]);
  }
  const x: string[] = [];
  const happy: (number | null)[] = [];
  const sad: (number | null)[] = [];
  for (let k = 0; k < weeks; k++) {
    const week = addDays(start, 7 * k);
    const s = shares(byWeek.get(week) ?? []);
    const enough = s.n >= 3;
    x.push(week);
    happy.push(enough ? Math.round((s.happy ?? 0) * 1000) / 1000 : null);
    sad.push(enough ? Math.round((s.sad ?? 0) * 1000) / 1000 : null);
  }
  return { x, happy, sad };
}

export function breakdown(user: User) {
  const rows = all<{ slot: string; study_date: string; rating: number }>(
    "SELECT slot, study_date, rating FROM ratings WHERE user_id = ?", user.id,
  );
  return {
    total: shares(rows.map((r) => r.rating)),
    bySlot: SLOTS.map((slot) => ({ label: slot, ...shares(rows.filter((r) => r.slot === slot).map((r) => r.rating)) })),
    byWeekday: WEEKDAYS.map((day, k) => ({
      label: day, ...shares(rows.filter((r) => weekdayIndex(r.study_date) === k).map((r) => r.rating)),
    })),
  };
}

/**
 * The protocol's safety rule: over the last 14 study days, more than half of at
 * least 10 reports were Sad, or the evening rating was 3 or lower on 7 days or more.
 */
export function safetyRuleMet(user: User, days = 14): boolean {
  const today = currentStudyDay(user).studyDate;
  const from = addDays(today, -(days - 1));
  const reports = get<{ n: number; sad: number }>(
    "SELECT count(*) AS n, coalesce(sum(rating = 1), 0) AS sad FROM ratings WHERE user_id = ? AND study_date BETWEEN ? AND ?",
    user.id, from, today,
  )!;
  const lowDays = get<{ n: number }>(
    "SELECT count(*) AS n FROM daily_logs WHERE user_id = ? AND date BETWEEN ? AND ? AND day_satisfaction <= 3", user.id, from, today,
  )!.n;
  return (reports.n >= 10 && reports.sad / reports.n > 0.5) || lowDays >= 7;
}

/** Reports since the study start, and how many came within an hour after a reminder in their slot. */
export function promptedReports(user: User): { reports: number; prompted: number } {
  const row = get<{ reports: number; prompted: number }>(
    `SELECT count(*) AS reports, coalesce(sum(EXISTS (
       SELECT 1 FROM reminders m WHERE m.user_id = r.user_id AND m.study_date = r.study_date AND m.slot = r.slot
         AND julianday(r.recorded_at) BETWEEN julianday(m.sent_at) AND julianday(m.sent_at) + 1.0 / 24)), 0) AS prompted
     FROM ratings r WHERE r.user_id = ? AND r.study_date >= ?`,
    user.id, studyStart(user) ?? "0000-01-01",
  )!;
  return row;
}

// Command line tasks. Run with: node scripts/cli.ts <command>
//
//   create-user NAME       password on stdin (use scripts/create-user.sh)
//   set-password NAME      password on stdin
