const [command, ...args] = process.argv.slice(2);
const log = (message: string) => console.log(`${new Date().toISOString()} ${message}`);

async function readStdin(): Promise<string> {
  const chunks: Buffer[] = [];
  for await (const chunk of process.stdin) chunks.push(chunk as Buffer);
  return Buffer.concat(chunks).toString("utf8").replace(/\r?\n$/, "");
}

const usersWithRatings = (only?: string) =>
  all<{ id: number; username: string; study_start: string | null }>(
    "SELECT DISTINCT u.id, u.username, u.study_start FROM users u JOIN ratings r ON r.user_id = u.id",
  )
    .filter((u) => !only || String(u.id) === only);

async function refit(ifNewData: boolean, only?: string): Promise<void> {
  markInterrupted();
  for (const user of usersWithRatings(only)) {
    const run = await refitUser(user.id, { ifNewData });
    if (!run) {
      log(`${user.username}: data unchanged or a refit is already running; skipped.`);
      continue;
    }
    log(`${user.username}: ${run.status}. ${run.message}`.trim());
    if (run.status !== "done") continue;
    // A fit that fails the convergence checks is kept for the private dashboard,
    // flagged, but never published.
    if (publishable(run, user.study_start)) log(await publish(run).catch((e: Error) => `Publishing failed: ${e.message}`));
    else log(`${user.username}: the fit failed the convergence checks or used another study start, so it was not published.`);
  }
}

/** One failing step (say, no network for weather) must not block the others. */
async function step(name: string, fn: () => Promise<unknown>): Promise<void> {
  try {
    await fn();
  } catch (error) {
    log(`${name} failed: ${(error as Error).message}`);
  }
}

switch (command) {
  case "create-user": {
    const name = args[0];
    if (!name) throw new Error("Usage: create-user NAME (password on stdin)");
    await createUser(name, await readStdin(), DEFAULT_TIME_ZONE);
    log(`Created ${name} (time zone ${DEFAULT_TIME_ZONE}; change it in Settings).`);
    break;
  }
  case "set-password": {
    const user = get<{ id: number }>("SELECT id FROM users WHERE username = ?", args[0] ?? "");
    if (!user) throw new Error(`No user named ${args[0]}`);
    await setPassword(user.id, await readStdin());
    log(`Password changed for ${args[0]}.`);
    break;
  }
  case "refit": {
    const i = args.indexOf("--user");
    await refit(false, i >= 0 ? args[i + 1] : undefined);
    break;
  }
  case "maintain":
    await step("Weather", async () => log(await syncWeather()));
    await step("Ultrahuman", async () => log(await syncUltrahuman()));
    await step("Indoor air", async () => log(await syncIndoorAir()));
    await step("Refit", () => refit(true));
    if (BACKUP_GPG_RECIPIENT && backupDue()) await step("Backup", async () => log(await backupNow()));
    break;
  case "sync-weather":
    log(await syncWeather(Number(args[0] ?? 7)));
    break;
  case "sync-ring":
    log(await syncUltrahuman(Number(args[0] ?? 3)));
    break;
  case "sync-air":
    log(await syncIndoorAir());
    break;
  case "alexa-login": {
    // The password and any one-time code go only to Amazon's own page, in the browser.
    const start = alexaSignInStart();
    console.log(`1. Open this address in your browser and sign in to Amazon:\n\n${start.url}\n`);
    console.log("2. After signing in, the browser shows an empty or \"not found\" page on amazon.com.");
    const prompt = createInterface({ input: process.stdin, output: process.stdout });
    const returned = await prompt.question("   Copy the whole address from the address bar, paste it here and press Enter:\n");
    prompt.close();
    await alexaSignInFinish(returned, start);
    log("Signed in. Reading the monitor once:");
    log(await syncIndoorAir());
    break;
  }
  case "backup":
    log(await backupNow());
    break;
  case "publish": {
    // Without a fit that passed the convergence checks, the pages go out alone
    // and any results.json already published stays as it is.
    const user = usersWithRatings()[0];
    const latest = user ? latestDone(user.id) : null;
    log(await publish(user && publishable(latest, user.study_start) ? latest : null, args[0]));
    break;
  }
  default:
    console.log("Commands: create-user, set-password, refit, maintain, sync-weather, sync-ring, sync-air, alexa-login, backup, publish");
    process.exitCode = command ? 1 : 0;
}
/* Keeps the mood page usable when the server is unreachable, and shows the
 * reminders the server pushes. Only the rating page and its assets are cached;
 * everything else always goes to the network. */
const CACHE = "asom-v3";
const PAGE = "/rate/";
const ASSETS = ["/static/css/app.css", "/static/js/rate.js", "/static/icons/icon-192.png"];

self.addEventListener("install", (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    await cache.addAll(ASSETS);
    // Cache the page only when signed in; a redirect to the login page is not cached.
    const page = await fetch(PAGE, { redirect: "manual", credentials: "same-origin" }).catch(() => null);
    if (page && page.ok) await cache.put(PAGE, page);
    await self.skipWaiting();
  })());
});

self.addEventListener("activate", (event) => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) if (key !== CACHE) await caches.delete(key);
    await self.clients.claim();
  })());
});

self.addEventListener("fetch", (event) => {
  const url = new URL(event.request.url);
  if (event.request.method !== "GET" || url.origin !== self.location.origin) return;
  if (url.pathname !== PAGE && !ASSETS.includes(url.pathname)) return;
  // Network first, so the page is fresh whenever the server answers.
  event.respondWith((async () => {
    try {
      const response = await fetch(event.request);
      if (response.ok && !response.redirected) {
        const cache = await caches.open(CACHE);
        await cache.put(url.pathname, response.clone());
      }
      return response;
    } catch (error) {
      return (await caches.match(url.pathname)) || Response.error();
    }
  })());
});

// A reminder: the payload carries only its text. Tapping it opens the rating page.
self.addEventListener("push", (event) => {
  let message = { title: "A Study On Myself", body: "How do you feel right now?", url: PAGE };
  try {
    if (event.data) message = { ...message, ...event.data.json() };
  } catch (error) {
    // an unreadable payload still gets the default reminder
  }
  event.waitUntil(self.registration.showNotification(message.title, {
    body: message.body, tag: "mood-" + (message.slot || "now"), icon: "/static/icons/icon-192.png", data: { url: message.url || PAGE },
  }));
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const url = (event.notification.data && event.notification.data.url) || PAGE;
  event.waitUntil((async () => {
    for (const client of await self.clients.matchAll({ type: "window", includeUncontrolled: true })) {
      if (new URL(client.url).pathname === url && "focus" in client) return client.focus();
    }
    return self.clients.openWindow(url);
  })());
});
/* One-tap mood reports with an offline queue.
 * Every report is stored on the device first (with its own timestamp and a
 * client_id) and then sent. If the server is asleep or unreachable it stays
 * queued and is sent later; the client_id keeps retries from duplicating it. */
(function () {
  "use strict";
  const KEY = "asom-queue";
  const widget = document.querySelector("[data-rate]");
  let csrfToken = document.querySelector('meta[name="csrf-token"]').content;
  let memory = [];

  if ("serviceWorker" in navigator) navigator.serviceWorker.register("/sw.js").catch(() => {});

  function load() {
    try { return JSON.parse(localStorage.getItem(KEY)) || []; } catch (e) { return memory; }
  }
  function store(queue) {
    try { localStorage.setItem(KEY, JSON.stringify(queue)); } catch (e) { memory = queue; }
  }
  function drop(id) { store(load().filter((q) => q.client_id !== id)); }
  function say(text) { if (widget) widget.querySelector("[data-status]").textContent = text; }
  function uuid() {
    if (crypto.randomUUID) return crypto.randomUUID();
    const b = crypto.getRandomValues(new Uint8Array(16));
    b[6] = (b[6] & 15) | 64; b[8] = (b[8] & 63) | 128;
    const h = [...b].map((x) => x.toString(16).padStart(2, "0")).join("");
    return `${h.slice(0, 8)}-${h.slice(8, 12)}-${h.slice(12, 16)}-${h.slice(16, 20)}-${h.slice(20)}`;
  }

  function post(item) {
    return fetch("/api/ratings/", {
      method: "POST",
      credentials: "same-origin",
      headers: { "Content-Type": "application/json", "X-CSRFToken": csrfToken },
      body: JSON.stringify(item),
    });
  }

  async function freshToken() {
    const r = await fetch("/csrf/", { credentials: "same-origin" });
    // Signed out: /csrf/ redirects to the login page, which is not JSON.
    if (!r.ok || !(r.headers.get("content-type") || "").includes("json")) throw new Error("signed out");
    csrfToken = (await r.json()).token;
  }

  async function saved(response) {
    if (!response.ok) return false;
    const body = await response.json().catch(() => null);
    return Boolean(body && body.id);
  }

  let busy = false;
  async function flush() {
    if (busy) return;
    busy = true;
    let signedOut = false, rejected = 0, sent = 0;
    try {
      for (const item of load()) {
        let r;
        try { r = await post(item); } catch (e) { break; } // offline: keep everything
        if (r.status === 403) {
          try { await freshToken(); r = await post(item); } catch (e) { signedOut = true; break; }
        }
        if (await saved(r)) { drop(item.client_id); sent += 1; }
        else if (r.status === 400) { rejected += 1; drop(item.client_id); }
        else { signedOut = r.status === 401 || r.status === 403; break; }
      }
    } finally {
      busy = false;
    }
    const left = load().length;
    if (signedOut) say(`${left} report(s) kept on this device. Sign in to send them.`);
    else if (left) say(`Kept on this device (${left} waiting). They will be sent when the server is reachable.`);
    else if (rejected) say(`${rejected} report(s) were too old or invalid and were discarded.`);
    else if (sent) say(`Sent ${sent} report(s) saved on this device.`);
    return left;
  }

  function record(mood) {
    const note = widget.querySelector("#rate-note");
    const tags = [...widget.querySelectorAll('[data-tag][aria-pressed="true"]')].map((b) => b.dataset.tag);
    const queue = load();
    queue.push({
      client_id: uuid(),
      rating: mood,
      recorded_at: new Date().toISOString(),
      time_zone: Intl.DateTimeFormat().resolvedOptions().timeZone,
      note: note ? note.value.trim() : "",
      tags,
      source: "web",
    });
    store(queue);
    say("Saving…");
    flush().then((left) => {
      if (left) return;
      say("Saved. Thank you.");
      if (note) note.value = "";
      widget.querySelectorAll("[data-tag]").forEach((b) => b.setAttribute("aria-pressed", "false"));
      if ("reload" in widget.dataset) setTimeout(() => location.reload(), 700);
    });
  }

  if (widget) {
    widget.querySelectorAll("[data-mood]").forEach((button) => {
      button.addEventListener("click", () => record(Number(button.dataset.mood)));
    });
    widget.querySelectorAll("[data-tag]").forEach((button) => {
      button.addEventListener("click", () => {
        button.setAttribute("aria-pressed", button.getAttribute("aria-pressed") === "true" ? "false" : "true");
      });
    });
  }
  window.addEventListener("online", flush);
  document.addEventListener("visibilitychange", () => { if (!document.hidden) flush(); });
  setInterval(flush, 60000);
  if (load().length) flush();
})();

function insertRating(user: auth.User, v: RatingInput): { status: number; row: Row } {
  const timeZone = v.timeZone ?? user.time_zone;
  const { studyDate, slot } = studyDayAndSlot(v.recordedAt, timeZone, user.day_start_hour);
  try {
    const id = run(
      `INSERT INTO ratings (user_id, rating, recorded_at, time_zone, study_date, slot, note, tags, source, client_id)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      user.id, v.rating, v.recordedAt.toISOString(), timeZone, studyDate, slot, v.note, JSON.stringify(v.tags), v.source, v.clientId,
    ).lastInsertRowid;
    return { status: 201, row: get<Row>(`SELECT ${RATING_COLUMNS} FROM ratings WHERE id = ?`, id)! };
  } catch (error) {
    // A retried offline submission (same client_id): acknowledge the stored copy.
    if (!String(error).includes("UNIQUE constraint failed")) throw error;
    return { status: 200, row: get<Row>(`SELECT ${RATING_COLUMNS} FROM ratings WHERE user_id = ? AND client_id = ?`, user.id, v.clientId)! };
  }
}

router.add("POST", "/api/ratings/", "api-write", (req) => {
  const { value, errors } = validateRating(req.body);
  if (!value) return json(errors, 400);
  const { status, row } = insertRating(req.user!, value);
  // A device token can add data but never read it back, so it gets an acknowledgment only.
  if (req.viaDevice) return json({ id: row.id, study_date: row.study_date, slot: row.slot }, status);
  return json(ratingJson(row), status);
});

