425	    for (let h = 0; h < 11; h++) readings.push({ measured_at: new Date(Date.UTC(2026, 8, 17, 12 + h)).toISOString(), metric: "voc", value: 100 });
426	    const means = sources.dailyAirMeans(readings, "America/Toronto");
427	    assert.deepEqual([...means.keys()], ["2026-09-18"]);
428	    assert.equal(means.get("2026-09-18")!.indoor_pm25, Math.round(((20 + 11 * 10) / 12) * 10) / 10);
429	  });
430	
431	  test("automatic values are saved only when they change", () => {
432	    assert.equal(mergeDaily(userId, "2026-01-02", { indoor_pm25: 5.5 }), true);
433	    assert.equal(mergeDaily(userId, "2026-01-02", { indoor_pm25: 5.5 }), false);
434	    run("DELETE FROM daily_logs WHERE user_id = ? AND date = ?", userId, "2026-01-02");
435	  });
436	
437	  test("the safety rule needs at least 10 reports, mostly Sad", () => {
438	    const user = { id: userId, username: "me", time_zone: "America/Toronto", day_start_hour: 4, study_start: null };
439	    const today = studyDayAndSlot(new Date(), "America/Toronto").studyDate;
440	    const add = (n: number) => {
441	      for (let i = 0; i < n; i++) {
442	        run("INSERT INTO ratings (user_id, rating, recorded_at, time_zone, study_date, slot, client_id) VALUES (?, 1, ?, ?, ?, 'evening', ?)",
443	          userId, new Date().toISOString(), "America/Toronto", today, crypto.randomUUID());
444	      }
445	    };
446	    const before = all<{ id: number }>("SELECT id FROM ratings WHERE user_id = ?", userId).map((r) => r.id);
447	    const existing = before.length;
448	    add(Math.max(0, 9 - existing));
449	    if (existing <= 9) assert.equal(safetyRuleMet(user), false);
450	    add(10);
451	    assert.equal(safetyRuleMet(user), true);
452	    run(`DELETE FROM ratings WHERE user_id = ? AND id NOT IN (${before.join(",") || "0"})`, userId);
453	  });
454	});
455	
456	describe("push reminders", () => {
457	  const b64 = (s: string) => Buffer.from(s.replace(/\s/g, ""), "base64url");
458	
459	  test("payload encryption matches the example in RFC 8291", () => {
460	    const body = push.encryptPayload(
461	      b64("V2hlbiBJIGdyb3cgdXAsIEkgd2FudCB0byBiZSBhIHdhdGVybWVsb24"),
462	      b64("BCVxsr7N_eNgVRqvHtD0zTZsEc6-VV-JvLexhqUzORcxaOzi6-AYWXvTBHm4bjyPjs7Vd8pZGH6SRpkNtoIAiw4"),
463	      b64("BTBZMqHH6r4Tts7J_aSIgg"), b64("DGv6ra1nlYgDCS1FRnbzlw"), b64("yfWPiYE-n46HLnH0KqZOF1fJJU3MYrct3AELtAQ-oRw"),
464	    );
465	    assert.equal(body.toString("base64url"),
466	      "DGv6ra1nlYgDCS1FRnbzlwAAEABBBP4z9KsN6nGRTbVYI_c7VJSPQTBtkgcy27mlmlMoZIIgDll6e3vCYLocInmYWAmS6TlzAC8wEqKK6PBru3jl7A_yl95bQpu6cVPT" +
467	      "pK4Mqgkf1CXztLVBSt2Ks3oZwbuwXPXLWyouBWLVWGNWQexSgSxsj_Qulcy4a-fN");
468	  });
469	
470	  test("the VAPID token is signed by the server's key for the push service's origin", () => {
471	    const header = push.vapidAuthorization("https://web.push.apple.com/QGuQyavXutnMH8/abc");
472	    const [, token, key] = /^vapid t=([^,]+), k=(.+)$/.exec(header)!;
473	    const [h, c, sig] = token.split(".");
474	    assert.equal(JSON.parse(Buffer.from(c, "base64url").toString()).aud, "https://web.push.apple.com");
475	    assert.equal(key, push.vapidPublicKey());
476	    const raw = Buffer.from(key, "base64url");
477	    const publicKey = createPublicKey({ key: { kty: "EC", crv: "P-256", x: raw.subarray(1, 33).toString("base64url"), y: raw.subarray(33).toString("base64url") }, format: "jwk" });
478	    assert.ok(verify("sha256", Buffer.from(`${h}.${c}`), { key: publicKey, dsaEncoding: "ieee-p1363" }, Buffer.from(sig, "base64url")));
479	  });
480	
481	  test("reminder times must fall in their slots", () => {
482	    assert.deepEqual(push.validateReminderTimes(["10:30", "15:30", "21:00"]).times, ["10:30", "15:30", "21:00"]);
483	    assert.ok(push.validateReminderTimes(["08:00", "12:00", "01:30"]).times); // the evening runs past midnight
484	    assert.ok(push.validateReminderTimes(["13:00", "15:30", "21:00"]).error);
485	    assert.ok(push.validateReminderTimes(["10:30", "15:30"]).error);
486	  });
487	
488	  test("a due slot without a report gets one encrypted reminder", async () => {
489	    const received: { headers: Record<string, unknown>; body: Buffer }[] = [];
490	    const service = createServer((req, res) => {
491	      const chunks: Buffer[] = [];
492	      req.on("data", (c: Buffer) => chunks.push(c)).on("end", () => {
493	        received.push({ headers: req.headers, body: Buffer.concat(chunks) });
494	        res.writeHead(201).end();
495	      });
496	    });
497	    await new Promise<void>((resolve) => service.listen(0, "127.0.0.1", resolve));
498	    const ua = createECDH("prime256v1");
499	    ua.generateKeys();
500	    const secret = Buffer.alloc(16, 7);
501	    const endpoint = `http://127.0.0.1:${(service.address() as { port: number }).port}/push/1`;
502	    run("INSERT INTO push_subscriptions (user_id, endpoint, p256dh, auth) VALUES (?, ?, ?, ?)",
503	      userId, endpoint, ua.getPublicKey().toString("base64url"), secret.toString("base64url"));
504	    try {
505	      // 15 January 2026, 10:40 in Toronto: the morning reminder (10:30) is due.
506	      const now = new Date("2026-01-15T15:40:00Z");
507	      assert.equal(await push.sendDueReminders(new Date("2026-01-15T15:20:00Z")), 0); // not yet due
508	      assert.equal(await push.sendDueReminders(now), 1);
509	      assert.equal(await push.sendDueReminders(now), 0); // once per slot
510	      assert.equal(received.length, 1);
511	      const { headers, body } = received[0];
512	      assert.equal(headers["content-encoding"], "aes128gcm");
513	      assert.ok(String(headers.authorization).startsWith("vapid t="));
514	      // Decrypt as the phone would.
515	      const asPublic = body.subarray(21, 21 + body[20]);
516	      const ikm = Buffer.from(hkdfSync("sha256", ua.computeSecret(asPublic), secret, Buffer.concat([Buffer.from("WebPush: info\0"), ua.getPublicKey(), asPublic]), 32));
517	      const derive = (info: string, n: number) => Buffer.from(hkdfSync("sha256", ikm, body.subarray(0, 16), Buffer.from(info), n));
518	      const cipherText = body.subarray(21 + body[20]);
519	      const decipher = createDecipheriv("aes-128-gcm", derive("Content-Encoding: aes128gcm\0", 16), derive("Content-Encoding: nonce\0", 12));
520	      decipher.setAuthTag(cipherText.subarray(-16));
521	      const plain = Buffer.concat([decipher.update(cipherText.subarray(0, -16)), decipher.final()]);
522	      assert.equal(JSON.parse(plain.subarray(0, -1).toString()).slot, "morning");
523	      // A report ten minutes after the reminder counts as answering it.
524	      const sentAt = all<{ sent_at: string }>("SELECT sent_at FROM reminders WHERE user_id = ? AND study_date = '2026-01-15'", userId)[0].sent_at;
525	      run("INSERT INTO ratings (user_id, rating, recorded_at, time_zone, study_date, slot, client_id) VALUES (?, 3, ?, ?, '2026-01-15', 'morning', ?)",
526	        userId, new Date(Date.parse(sentAt) + 10 * 60_000).toISOString(), "America/Toronto", crypto.randomUUID());
527	      const user = { id: userId, username: "me", time_zone: "America/Toronto", day_start_hour: 4, study_start: null };
528	      assert.ok(stats.promptedReports(user).prompted >= 1);
529	      // A slot that already has a report is not reminded.
530	      run("INSERT INTO ratings (user_id, rating, recorded_at, time_zone, study_date, slot, client_id) VALUES (?, 2, ?, ?, '2026-01-15', 'afternoon', ?)",
531	        userId, "2026-01-15T19:00:00Z", "America/Toronto", crypto.randomUUID());
532	      assert.equal(await push.sendDueReminders(new Date("2026-01-15T21:00:00Z")), 0);
533	    } finally {
534	      run("DELETE FROM push_subscriptions WHERE endpoint = ?", endpoint);
535	      run("DELETE FROM reminders WHERE user_id = ?", userId);
536	      run("DELETE FROM ratings WHERE user_id = ? AND study_date = '2026-01-15'", userId);
537	      service.close();
538	    }
539	  });
540	});
541	
